// ─── File: src/main/java/com/nbi/jv/model/AccountView.java ───
package com.nbi.jv.model;

import com.fasterxml.jackson.annotation.JsonView;
import com.nbi.jv.view.Views;
import java.math.BigDecimal;

// ONE class, fields tagged per view → different subsets without many DTOs.
public class AccountView {
    @JsonView(Views.Summary.class) private String accountId;
    @JsonView(Views.Summary.class) private String holderName;
    @JsonView(Views.Summary.class) private BigDecimal balance;
    @JsonView(Views.Detail.class)  private String branchCode;      // detail + admin
    @JsonView(Views.Admin.class)   private int internalRiskScore;  // admin only

    public AccountView(String accountId, String holderName, BigDecimal balance,
                       String branchCode, int internalRiskScore) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
        this.branchCode = branchCode; this.internalRiskScore = internalRiskScore;
    }
    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public String getBranchCode() { return branchCode; }
    public int getInternalRiskScore() { return internalRiskScore; }
}
```

