```java
// ─── File: src/main/java/com/nbi/jv/controller/AccountController.java ───
package com.nbi.jv.controller;

import com.fasterxml.jackson.annotation.JsonView;
import com.nbi.jv.dto.DashboardResponse;
import com.nbi.jv.model.AccountView;
import com.nbi.jv.service.AccountService;
import com.nbi.jv.view.Views;
import org.springframework.http.converter.json.MappingJacksonValue;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    // Static views via @JsonView on the method — one model, three subsets.
    @GetMapping("/{id}/summary")
    @JsonView(Views.Summary.class)
    public AccountView summary(@PathVariable String id) { return service.get(id); }

    @GetMapping("/{id}/detail")
    @JsonView(Views.Detail.class)
    public AccountView detail(@PathVariable String id) { return service.get(id); }

    @GetMapping("/{id}/admin")
    @JsonView(Views.Admin.class)
    public AccountView admin(@PathVariable String id) { return service.get(id); }

    // DYNAMIC view chosen at runtime by role via MappingJacksonValue.
    @GetMapping("/{id}")
    public MappingJacksonValue byRole(@PathVariable String id,
            @RequestHeader(value = "X-Role", defaultValue = "CUSTOMER") String role) {
        MappingJacksonValue wrapper = new MappingJacksonValue(service.get(id));
        wrapper.setSerializationView("ADMIN".equals(role)
                ? Views.Admin.class : Views.Summary.class);
        return wrapper;
    }

    // Dedicated DTO: combined models + computed field → JsonView does NOT fit.
    @GetMapping("/{id}/dashboard")
    public DashboardResponse dashboard(@PathVariable String id) {
        return service.dashboard(id);
    }
}
```
